mapper.select:
SELECT  FROM t_message
WHERE deleted = 0


        AND ((sender_id = #{userId} AND receiver_id = #{targetId})
             OR (sender_id = #{targetId} AND receiver_id = #{userId}))


        AND receiver_id = #{targetId}



  AND msg_id < #{beforeMsgId}

ORDER BY msg_id DESC
LIMIT #{limit}

SELECT  FROM t_message
WHERE deleted = 0
  AND receiver_id = #{groupId}
  AND receiver_type = 2
  AND sender_id != #{userId}
  AND created_at > #{afterTime}
ORDER BY msg_id ASC

SELECT  FROM t_message
WHERE deleted = 0
  AND status = #{status}
  AND created_at < #{cutoff}
ORDER BY created_at ASC
LIMIT 500
